{"implementation":"def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for v, g in refinement.items():
        members.setdefault(g, []).append(v)
    for g in members:
        members[g].sort()
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        if gu != gv:
            key = (gu, gv)
            agg[key] = agg.get(key, 0) + w
    aggregate_edges = [[gu, gv, total] for (gu, gv), total in sorted(agg.items())]
    return {'members': members, 'aggregate_edges': aggregate_edges}"}
